CREATE TABLE `hardware_parts` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`sku` text NOT NULL,`category` text NOT NULL,`status` text DEFAULT 'draft' NOT NULL,`current_version_id` integer,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `hardware_parts_sku_unique` ON `hardware_parts` (`sku`); CREATE INDEX `hardware_parts_category_status_idx` ON `hardware_parts` (`category`,`status`);
CREATE TABLE `hardware_versions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`hardware_part_id` integer NOT NULL,`version` integer NOT NULL,`name_en` text NOT NULL,`name_zh` text NOT NULL,`brand` text DEFAULT '' NOT NULL,`supplier` text DEFAULT '' NOT NULL,`dimensions_json` text DEFAULT '{}' NOT NULL,`finish_color` text DEFAULT '' NOT NULL,`capacity` real,`clearance_sixteenths` integer DEFAULT 0 NOT NULL,`pack_quantity` real DEFAULT 1 NOT NULL,`unit` text DEFAULT 'each' NOT NULL,`installation_notes` text DEFAULT '' NOT NULL,`motor_protocol` text DEFAULT '' NOT NULL,`voltage` text DEFAULT '' NOT NULL,`control_compatibility_json` text DEFAULT '[]' NOT NULL,`product_compatibility_json` text DEFAULT '[]' NOT NULL,`supplier_cost` real,`sales_reference_price` real,`currency` text DEFAULT 'USD' NOT NULL,`effective_from` text NOT NULL,`effective_to` text,`lead_time_days` integer DEFAULT 0 NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `hardware_versions_part_version_unique` ON `hardware_versions` (`hardware_part_id`,`version`); CREATE INDEX `hardware_versions_part_idx` ON `hardware_versions` (`hardware_part_id`);
CREATE TABLE `hardware_compatibility_rules` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`source_part_id` integer NOT NULL,`target_part_id` integer NOT NULL,`relationship` text NOT NULL,`reason` text DEFAULT '' NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `hardware_compatibility_pair_unique` ON `hardware_compatibility_rules` (`source_part_id`,`target_part_id`,`relationship`);
